/**
 * @file test-audio-song.c
 * @brief 从 Flash 读取歌曲 PCM，通过 GPT6 差分 PWM 驱动 J8 喇叭。
 *
 * MP3 由电脑端 scripts/mp3_to_array.py 解码；板端只播放单声道 PCM。
 * 本文件包含初始化、采样中断、停止清理和歌曲数组，不调用其他测试。
 * 阅读顺序：线程入口 → run_test → audio_tick；末尾数组由脚本生成。
 */
#include <rtthread.h>
#include "hal_data.h"

enum
{
    TEST_PASS = 0,
    TEST_WAIT = 1
};

/* BEGIN GENERATED SONG METADATA */
/* 由 scripts/mp3_to_array.py 生成；数组保存解码后的 PCM，不是 MP3 压缩字节。
 * 输入 MP3 SHA256: 4b2ec2bc795ed08ccfadb28dc4569a9d0869041ab051b27450c56f1c9f2ba4d0 */
#define SONG_SAMPLE_RATE 16000u
#define SONG_SAMPLE_COUNT 195729u
#define SONG_PCM_PEAK 3000u
/* END GENERATED SONG METADATA */

#define AUDIO_PWM_PERIOD_COUNTS 1500u
#define AUDIO_PWM_CENTER_COUNTS 750
#define AUDIO_SAMPLE_LIMIT 3000
#define AUDIO_TIMER_CLOCK_HZ 120000000u
#define AUDIO_SAMPLE_PERIOD_COUNTS (AUDIO_TIMER_CLOCK_HZ / SONG_SAMPLE_RATE)
#define AUDIO_PLAYBACK_TIMEOUT_MS (SONG_SAMPLE_COUNT * 1000u / SONG_SAMPLE_RATE + 2000u)

/* 数组定义放在末尾，先声明便于前面的播放逻辑访问；不会复制整首歌到 RAM。 */
static const int16_t song_pcm[SONG_SAMPLE_COUNT];
/* 线程在启动 GPT2 前清零，中断更新；volatile 保证线程每次重新读取。 */
static volatile unsigned playback_position;
static volatile fsp_err_t playback_error;

/* argument 为可选事件对象，bit0 请求停止；不清除事件，让退出路径也能读到。 */
static int test_cancelled(void)
{
    rt_event_t stop_event = (rt_event_t)rt_thread_self()->parameter;
    rt_uint32_t received = 0;
    if (stop_event == RT_NULL)
    {
        return 0;
    }
    return rt_event_recv(stop_event, 1, RT_EVENT_FLAG_OR, 0, &received) == RT_EOK;
}

/* 无符号 tick 差值允许系统计时回绕；播放等待始终有时间上限。 */
static int test_elapsed(rt_tick_t start, unsigned milliseconds)
{
    return (rt_tick_t)(rt_tick_get() - start) >= rt_tick_from_millisecond(milliseconds);
}

/* 只恢复当前 PWM 引脚的 FSP 复用，不重新配置整张引脚表。 */
static int configure_pwm_pin(bsp_io_port_pin_t pin)
{
    for (unsigned index = 0; index < g_bsp_pin_cfg.number_of_pins; ++index)
    {
        if (g_bsp_pin_cfg.p_pin_cfg_data[index].pin == pin)
        {
            fsp_err_t error = R_IOPORT_PinCfg(&g_ioport_ctrl, pin,
                                             g_bsp_pin_cfg.p_pin_cfg_data[index].pin_cfg);
            if (error != FSP_SUCCESS)
            {
                rt_kprintf("SONG pin configuration error=%d\n", error);
                return -RT_ERROR;
            }
            return TEST_PASS;
        }
    }
    rt_kprintf("SONG PWM pin missing from generated configuration\n");
    return -RT_ERROR;
}

/* 关闭定时器后，让 P702/P703 都输出低电平，停止桥式电路的差分驱动。 */
static int mute_output_pins(void)
{
    int result = TEST_PASS;
    fsp_err_t error = R_IOPORT_PinCfg(&g_ioport_ctrl, BSP_IO_PORT_07_PIN_02,
                                     IOPORT_CFG_PORT_DIRECTION_OUTPUT | IOPORT_CFG_PORT_OUTPUT_LOW);
    if (error != FSP_SUCCESS)
    {
        result = -RT_ERROR;
    }
    error = R_IOPORT_PinCfg(&g_ioport_ctrl, BSP_IO_PORT_07_PIN_03,
                          IOPORT_CFG_PORT_DIRECTION_OUTPUT | IOPORT_CFG_PORT_OUTPUT_LOW);
    if (error != FSP_SUCCESS)
    {
        result = -RT_ERROR;
    }
    return result;
}

/* GPT2 每 62.5us 取一个样本；中断只做整数运算和占空比更新，不打印日志。
 * 播完后继续输出中点，避免最后一个样本成为持续的直流差分输出。 */
static void audio_tick(timer_callback_args_t *arguments)
{
    int sample = 0;
    RT_UNUSED(arguments);
    if (playback_position < SONG_SAMPLE_COUNT)
    {
        sample = song_pcm[playback_position];
        ++playback_position;
    }
    /* 脚本已控制峰值；中断仍保留限幅，防止手动修改数组后输出过大。 */
    if (sample > AUDIO_SAMPLE_LIMIT)
    {
        sample = AUDIO_SAMPLE_LIMIT;
    }
    if (sample < -AUDIO_SAMPLE_LIMIT)
    {
        sample = -AUDIO_SAMPLE_LIMIT;
    }
    /* 有符号 PCM 的 0 对应两路 50%；正负样本让两桥臂占空比相反变化。 */
    int duty_offset = sample * AUDIO_PWM_CENTER_COUNTS / 32768;
    fsp_err_t error = R_GPT_DutyCycleSet(&g_timer6_ctrl,
                                        AUDIO_PWM_CENTER_COUNTS + duty_offset, GPT_IO_PIN_GTIOCA);
    if (error != FSP_SUCCESS)
    {
        playback_error = error;
    }
    error = R_GPT_DutyCycleSet(&g_timer6_ctrl,
                             AUDIO_PWM_CENTER_COUNTS - duty_offset, GPT_IO_PIN_GTIOCB);
    if (error != FSP_SUCCESS)
    {
        playback_error = error;
    }
}

/* 停止与关闭分别检查，便于发现退出时的硬件错误；只能用于本次已打开的 GPT。 */
static int close_timer(gpt_instance_ctrl_t *control)
{
    int result = TEST_PASS;
    fsp_err_t error = R_GPT_Stop(control);
    if (error != FSP_SUCCESS)
    {
        rt_kprintf("SONG timer stop error=%d\n", error);
        result = -RT_ERROR;
    }
    error = R_GPT_Close(control);
    if (error != FSP_SUCCESS)
    {
        rt_kprintf("SONG timer close error=%d\n", error);
        result = -RT_ERROR;
    }
    return result;
}

/* 从局部配置启动 PWM 和采样时钟；歌曲只播放一遍，所有退出路径统一清理。 */
static int run_test(void)
{
    timer_cfg_t pwm_config = g_timer6_cfg;
    timer_cfg_t sample_config = g_timer2_cfg;
    int pwm_opened = 0;
    int sample_opened = 0;
    int result = -RT_ERROR;
    fsp_err_t error;
    playback_position = 0;
    playback_error = FSP_SUCCESS;

    /* 当前工程 PCLKD=120MHz，GPT 不分频：载波 80kHz，PCM 更新 16kHz。
     * 时钟不符时拒绝播放，避免移植后音调和时长悄悄发生变化。 */
    if (R_FSP_SystemClockHzGet(FSP_PRIV_CLOCK_PCLKD) != AUDIO_TIMER_CLOCK_HZ ||
        SONG_SAMPLE_RATE != 16000u || SONG_SAMPLE_COUNT == 0u || SONG_PCM_PEAK > AUDIO_SAMPLE_LIMIT)
    {
        rt_kprintf("SONG unsupported clock or PCM metadata\n");
        goto cleanup;
    }
    if (test_cancelled())
    {
        result = -RT_EINTR;
        goto cleanup;
    }
    if (configure_pwm_pin(BSP_IO_PORT_07_PIN_02) != TEST_PASS ||
        configure_pwm_pin(BSP_IO_PORT_07_PIN_03) != TEST_PASS)
    {
        goto cleanup;
    }
    pwm_config.source_div = TIMER_SOURCE_DIV_1;
    pwm_config.mode = TIMER_MODE_PERIODIC;
    pwm_config.period_counts = AUDIO_PWM_PERIOD_COUNTS;
    pwm_config.duty_cycle_counts = AUDIO_PWM_CENTER_COUNTS;
    sample_config.source_div = TIMER_SOURCE_DIV_1;
    sample_config.mode = TIMER_MODE_PERIODIC;
    sample_config.period_counts = AUDIO_SAMPLE_PERIOD_COUNTS;
    sample_config.duty_cycle_counts = AUDIO_SAMPLE_PERIOD_COUNTS / 2u;
    sample_config.p_callback = audio_tick;

    error = R_GPT_Open(&g_timer6_ctrl, &pwm_config);
    if (error != FSP_SUCCESS)
    {
        rt_kprintf("SONG PWM open error=%d\n", error);
        goto cleanup;
    }
    pwm_opened = 1;
    error = R_GPT_Start(&g_timer6_ctrl);
    if (error != FSP_SUCCESS)
    {
        rt_kprintf("SONG PWM start error=%d\n", error);
        goto cleanup;
    }
    error = R_GPT_Open(&g_timer2_ctrl, &sample_config);
    if (error != FSP_SUCCESS)
    {
        rt_kprintf("SONG sample timer open error=%d\n", error);
        goto cleanup;
    }
    sample_opened = 1;
    rt_kprintf("SONG PCM mono rate=%u samples=%u bytes=%u peak=%u duration=%u ms\n",
               SONG_SAMPLE_RATE, SONG_SAMPLE_COUNT, (unsigned)sizeof(song_pcm), SONG_PCM_PEAK,
               SONG_SAMPLE_COUNT * 1000u / SONG_SAMPLE_RATE);
    rt_kprintf("SONG playing once on J8; PWM=80kHz, source=offline decoded MP3\n");
    error = R_GPT_Start(&g_timer2_ctrl);
    if (error != FSP_SUCCESS)
    {
        rt_kprintf("SONG sample timer start error=%d\n", error);
        goto cleanup;
    }

    rt_tick_t start = rt_tick_get();
    while (playback_position < SONG_SAMPLE_COUNT && playback_error == FSP_SUCCESS)
    {
        if (test_cancelled())
        {
            result = -RT_EINTR;
            goto cleanup;
        }
        if (test_elapsed(start, AUDIO_PLAYBACK_TIMEOUT_MS))
        {
            result = -RT_ETIMEOUT;
            goto cleanup;
        }
        rt_thread_mdelay(1);
    }
    if (playback_error == FSP_SUCCESS && playback_position == SONG_SAMPLE_COUNT)
    {
        result = TEST_WAIT;
    }

cleanup:
    /* 先关闭采样中断，再关闭 PWM；中断不能继续访问已经关闭的 GPT6。 */
    if (sample_opened)
    {
        if (close_timer(&g_timer2_ctrl) != TEST_PASS)
        {
            result = -RT_ERROR;
        }
    }
    if (pwm_opened)
    {
        if (close_timer(&g_timer6_ctrl) != TEST_PASS)
        {
            result = -RT_ERROR;
        }
    }
    if (mute_output_pins() != TEST_PASS)
    {
        result = -RT_ERROR;
    }
    rt_kprintf("SONG output samples=%u/%u pwm_error=%d; listening confirmation required\n",
               playback_position, SONG_SAMPLE_COUNT, playback_error);
    return result;
}

/* 唯一线程入口：独立初始化、播放和清理，自然返回，由调用方回收线程。
 * error 保存结果；完整播放仍返回 WAIT，歌曲有声、内容与音质需要人耳验收。 */
void test_audio_song_thread(void *argument)
{
    int result;
    RT_UNUSED(argument);
    result = run_test();
    if (test_cancelled())
    {
        result = -RT_EINTR;
    }
    rt_thread_self()->error = result;
}

